model_config.built_in_css:
/* ========== A. 双端生效（Web + App）：正文层 ========== */
.markdown-body {
    color: #443c52;
    background-color: #f1e4ff; /* App端只能看到这一层，保留你喜欢的底色 */
    border-radius: 10px;
}

/* ========== 以下 B~F 仅网页端生效 ========== */

/* ========== B. 永久隐藏头像 + 收回留白 ========== */
#customized-question-avatar,
#customized-answer-avatar { display: none; }
#customized-question-avatar + div,
#ai-chat-answer .chat-answer-container,
#ai-chat-answer .chat-answer-container > div {
    margin: 0;
}
/* B2. 气泡本体：水平 margin 用你调好的值；上下 margin 两边必须相同（这里都是 7px） */
#customized-question-content {
    margin: 7px 20px;              /* 上下7 左右20 —— 你调好的宽度 */
    width: auto;
    max-width: calc(100% - 40px);
}
#customized-answer-content {
    margin: 7px 6px;               /* 上下7 左右6 —— 你调好的宽度 */
    width: auto;
    max-width: calc(100% - 20px);
}

/* B3. 行 + 所有 wrapper 层的上下边距/内边距强制归零，
      间距只由气泡的上下 margin 产生 → 每次必然相等 */
div:has(> #customized-question-content),          /* 用户框的 wrapper */
div:has(> div > #customized-question-content),    /* 用户行 */
div:has(> #customized-answer-content),            /* AI框的内层 wrapper */
div:has(> div > #customized-answer-content),      /* AI框的外层容器 */
#ai-chat-answer {                                 /* AI行 */
    margin-top: 0 !important;
    margin-bottom: -5 !important;
    padding-top: 0 !important;
    padding-bottom: 0 !important;
}

/* ========== C. 气泡框：用户蓝 / AI粉 ========== */
#customized-question-content {
    background: #e8f4ff;
    border: 2px solid #8fbce0;
    border-radius: 14px;
    box-shadow: 0 2px 10px rgba(143,188,224,.25);
}
#customized-answer-content {
    background: #f1e4ff;
    border: 2px solid #e88f8f;
    border-radius: 14px;
    box-shadow: 0 2px 10px rgba(232,143,143,.22);
}
#customized-question-content .markdown-body,
#customized-answer-content .markdown-body { background: transparent; }

/* ========== D. 时间戳 / 积分行 / 操作小图标 ========== */
#customized-question-content .text-text-secondary,
#customized-answer-content-created-time {
    color: #b3a3c9;
    font-size: 11px;
}
#customized-question-content .text-text-secondary::before,
#customized-answer-content-created-time::before { content: "♡ "; color: #e8a7c3; }

#customized-answer-content-model {
    background: rgba(255,255,255,.55);
    border-radius: 999px;
    padding: 2px 10px;
    width: fit-content;
}
#customized-answer-content-model p { font-size: 11px; }
#customized-answer-content-model-name { color: #9b7fd4; }

/* 操作小按钮：改用"气泡内所有button"，免疫UI库迁移；
   补 border:none 防止第4节 dialog-trigger 规则给它们描粉边 */
#customized-question-content button,
#customized-answer-content button {
    background: rgba(255,255,255,.65);
    border: none;
    color: #8f7fb8;
    padding: 2px 8px;
    border-radius: 999px !important; /* 保留：按钮带内联 style="border-radius:6px"，裸奔压不住 */
}

/* ========== E. 分页 + 工具栏 ========== */
#customized-pagination [data-slot="pagination-item"],
#customized-pagination [data-slot="pagination-link"],
#customized-pagination [data-slot="input"] {
    border-radius: 999px;
    border-color: #f3d3e3;
    background: #fff;
    color: #c48db2;
}
#customized-pagination [data-slot="pagination-link"][data-active="true"] {
    background: #fdeef5;
    border-color: #f0b9d0;
    color: #e07ba8;
}
#customized-pagination .text-muted-foreground { color: #c9a9bd; }

#ai-mod-button2 button {
    background: #fff;
    border: 1px solid #f0d4e4;
    color: #b58ab8;
    box-shadow: 0 1px 4px rgba(220,180,210,.25);
    border-radius: 999px !important; /* 保留：同上，内联6px圆角 */
}

/* ========== F. 输入区 + 发送 + 底部渐变 ========== */
div:has(> div > #ai-chat-input) {
    background: #fff;
    border-color: #e7c9e9;
    border-radius: 18px;
    box-shadow: 0 2px 12px rgba(210,170,220,.18);
}
#ai-chat-input { color: #5a4a6a; }
#ai-chat-input::placeholder { color: #c9b3d6; }
div:has(> #ai-send-button) { background: rgba(255,255,255,.7); }
#ai-send-button svg { color: #d384b5; }
.bg-gradient-to-t.from-white.via-white.to-transparent {
    background: linear-gradient(to top, #fef7fb 60%, rgba(254,247,251,0));
}

/* =========================================================
   💗 纯爱风格美化 · 历史聊天页 + 评论区
   ========================================================= */

/* ---------- 1. 主题变量换肤 ---------- */
:root {
  --color-primary: #ff5c8a;
  --color-primary-foreground: #ffffff;
  --color-primary-secondary: #ffe1ec;
  --color-background: #fff8fa;
  --color-foreground: #55404a;
  --color-muted: #ffeef4;
  --color-secondary: #ffeaf2;
  --color-secondary-foreground: #d6336c;
  --color-border: #ffd6e3;
  --color-input: #ffd6e3;
  --color-ring: #ff9dbd;
  --color-text-main: #4b3540;
  --color-text-secondary: #a58595;
  --color-text-tertiary: #c9adb9;
  --color-warning: #ff7bac;
}

/* ---------- 2. 全局底色 & 漂浮爱心 ---------- */
#installedBuiltInCss {
  background:
    radial-gradient(circle at 12% 18%, rgba(255,182,203,.18), transparent 42%),
    radial-gradient(circle at 88% 72%, rgba(255,143,179,.14), transparent 46%),
    linear-gradient(180deg, #fff9fb 0%, #fff1f6 100%);
}
#installedBuiltInCss::before,
#installedBuiltInCss::after {
  position: fixed; z-index: 0; pointer-events: none; opacity: .10;
  animation: fy-float 9s ease-in-out infinite;
}
#installedBuiltInCss::before { content:"💗"; top:14%; left:5%; font-size:110px; }
#installedBuiltInCss::after  { content:""; bottom:10%; right:5%; font-size:92px; animation-delay:-4.5s; }
@keyframes fy-float {
  0%,100% { transform: translateY(0) rotate(-8deg); }
  50%     { transform: translateY(-20px) rotate(8deg); }
}

/* ---------- 3. 吸顶栏 & 模型选择器 & 状态徽章 ---------- */
.sticky.top-0.backdrop-blur-md {
  background: rgba(255,244,248,.82);
  border-bottom: 1px solid #ffdbe7;
}
#ai-model-selector .rounded-md {
  background: #ffeaf2;
  outline: 1px solid #ffc9da;
}
#ai-model-selector .truncate { color: #d6336c; }
.bg-green-100 { background: #ffe1ec !important; } /* 保留：与平台工具类同级，防注入顺序 */
.text-green-800 { color: #d6336c !important; }    /* 保留：同上 */

/* ---------- 4. 按钮体系 ---------- */
[data-slot="button"] { border-radius: 999px !important; /* 保留：与 rounded-* 工具类同级 */ transition: all .25s ease; }
[data-slot="button"][data-variant="default"],
.bg-primary.text-primary-foreground {
  background: linear-gradient(135deg, #ff8fb3 0%, #ff5c8a 100%);
  color: #fff;
  border: none;
  box-shadow: 0 4px 14px rgba(255,92,138,.35);
}
[data-slot="button"][data-variant="default"]:hover { animation: fy-heartbeat .9s ease-in-out infinite; }
@keyframes fy-heartbeat { 0%,100%{transform:scale(1)} 50%{transform:scale(1.05)} }
[data-slot="button"][data-variant="outline"],
[data-slot="dialog-trigger"] {
  background: #fff;
  border: 1px solid #ffc9da;
  color: #e05586;
}
[data-slot="button"][data-variant="outline"]:hover,
[data-slot="dialog-trigger"]:hover {
  background: #ffeef4;
  box-shadow: 0 2px 10px rgba(255,143,179,.28);
}
button.border-warning { color: #ff5c8a; border-color: #ff9dbd; }
[data-slot="button"][data-variant="ghost"]:hover { background: #ffe1ec !important; /* 保留：与平台hover工具类同级 */ color: #e05586; }
button[data-expand] {
  background: #fff;
  border: 1px solid #ffc9da;
  color: #e05586;
  box-shadow: 0 2px 10px rgba(255,143,179,.30);
}
.more-icon { color: #c9adb9; }
.more-icon:hover, [data-active="true"] .more-icon { color: #ff5c8a; }

/* ---------- 5. 侧边栏 ---------- */
.line-clamp-2.text-xl { color: #d6336c; }
.line-clamp-2.text-xl::before { content: "💕 "; }
[data-slot="separator"] {
  border: none !important; /* 保留：与平台边框类同级 */
  height: 1px !important;
  background: linear-gradient(90deg, transparent, #ffc9da 18%, #ff8fb3 50%, #ffc9da 82%, transparent) !important;
}
div[role="presentation"][data-active] {
  background: #ffeef4;
  border-color: transparent;
  border-radius: 10px;
}
div[role="presentation"][data-active="true"] {
  background: linear-gradient(90deg, #ffe1ec, #fff4f8);
  border-color: #ff8fb3;
  box-shadow: 0 2px 8px rgba(255,143,179,.18);
}
div[role="presentation"][data-active]:hover { background: #ffe1ec; }
div[role="presentation"][data-active] .line-clamp-1 { color: #c2557f; }
div[role="presentation"][data-active="true"] .line-clamp-1 { color: #e05586; font-weight: 600; }

/* ---------- 6. 评论区面板 ---------- */
.chat-container > [role="presentation"] {
  background: linear-gradient(180deg, #fffafc 0%, #fff3f8 100%);
}
.chat-container button.border-b-2 { color: #b58ca0; border-bottom-color: transparent; }
.chat-container button.border-b-2.border-primary { color: #e05586; border-bottom-color: #ff5c8a; }
.chat-container button.border-b-2.border-primary::after { content: " ♥"; color: #ff9dbd; }
.chat-container button.absolute.top-2.right-2 { background: rgba(255,92,138,.55); color: #fff; }
.chat-container button.absolute.top-2.right-2:hover { background: rgba(255,92,138,.9); }

/* ---------- 7. 评分星星 ---------- */
.fy-rating-empty  { fill: #ffd9e4 !important; color: #ffd9e4 !important; } /* 保留：平台自定义类同级 */
.fy-rating-filled {
  fill: #ff5c8a !important; color: #ff5c8a !important;
  filter: drop-shadow(0 0 4px rgba(255,92,138,.45));
}
span.text-warning.w-14 { color: #ff5c8a; font-weight: 700; }

/* ---------- 8. 评论输入框 ---------- */
div:has(> textarea[placeholder="发表评论"]) {
  background: #fff;
  border: 1.5px solid #ffc9da;
  border-radius: 18px;
  box-shadow: 0 4px 18px rgba(255,143,179,.16);
  transition: box-shadow .25s ease, border-color .25s ease;
}
div:has(> textarea[placeholder="发表评论"]):focus-within {
  border-color: #ff8fb3;
  box-shadow: 0 0 0 3px rgba(255,143,179,.18), 0 6px 22px rgba(255,143,179,.28);
}
textarea[placeholder="发表评论"] { color: #4b3540; }
textarea[placeholder="发表评论"]::placeholder { color: #c9adb9; }
.h-5.rounded-md.bg-secondary { background: #ffe1ec; color: #e05586; }
.lucide-smile, .lucide-image { color: #ff8fb3 !important; /* 保留：与图标自带颜色类同级 */ transition: transform .2s ease, color .2s ease; }
[data-slot="popover-trigger"]:hover .lucide-smile,
[data-slot="tooltip-trigger"]:hover .lucide-image { color: #ff5c8a; transform: scale(1.18) rotate(-6deg); }
svg[data-icon="Send03"] { color: #ff5c8a; }
div:has(> svg[data-icon="Send03"]) { transition: background .2s ease; border-radius: 10px; }
div:has(> svg[data-icon="Send03"]):hover { background: #ffe1ec; }

/* ---------- 9. 评论条目卡片化（推测节，失效可整节删除） ---------- */
.overflow-y-auto.p-3.h-full > div:not([class*="mb-4"]) {
  background: #fff;
  border: 1px solid #ffe3ed;
  border-radius: 14px;
  padding: 12px 14px;
  margin-bottom: 12px;
  box-shadow: 0 2px 10px rgba(255,143,179,.08);
}

/* ---------- 10. 粉色滚动条 ---------- */
::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: #ffc9da; border-radius: 8px; }
::-webkit-scrollbar-thumb:hover { background: #ff9dbd; }
* { scrollbar-width: thin; scrollbar-color: #ffc9da transparent; }

 /* 直播间*/
.live-container {
background-color: rgba(0, 0, 0, 0.5);
padding: 15px;
border-radius: 8px;
color: #f0f0f0;
font-size: 14px;
}
.status-row {
display: flex;
justify-content: space-between;
margin-bottom: 8px;
}
.status-row.topic {
font-size: 16px;
font-weight: bold;
justify-content: center;
margin-bottom: 12px;
}
.status-info strong {
color: #ffeb3b;
margin-left: 5px;
}
.separator {
border: none;
border-top: 1px solid rgba(255, 255, 255, 0.2);
margin: 12px 0;
}
.danmu-area {
overflow: hidden;
}
.danmu-track {
position: relative;
display: flex;
align-items: center;
width: max-content;
height: 32px;
margin-bottom: 6px;
animation: danmu-fly 15s linear infinite;
}
.danmu-track span {
flex-shrink: 0;
padding: 4px 12px;
margin-right: 30px;
background: rgba(0, 0, 0, 0.5);
border-radius: 15px;
font-size: 13px;
white-space: nowrap;
}
.danmu-track:nth-child(1) {
animation-duration: 20s;
animation-delay: -7s;
}
.danmu-track:nth-child(2) {
animation-duration: 24s;
animation-delay: -3s;
}
.danmu-track:nth-child(3) {
animation-duration: 17s;
animation-delay: -9s;
}
@keyframes danmu-fly {
0% {
left: 100%;
transform: translateX(0);
}
100% {
left: 0;
transform: translateX(-100%);
}
}

.status-bar-container {
    width: 90%;
    max-width: 450px;
    margin: 25px auto;
    background-color: #ffffff;
    border-radius: 10px;
    box-shadow: 0 3px 10px rgba(0, 0, 0, 0.1);
    overflow: hidden; /* 需要 overflow: hidden 来配合动画 */
    border: 1px solid #e0e0e0;
}
/* details 元素的基本样式 */
.status-details {
    /* details 默认有一些边距，可以重置 */
    margin: 0;
    padding: 0;
}
/* summary 元素 (可点击的标题) */
.status-summary {
    display: flex; /* 使用 Flexbox 布局内部元素 */
    justify-content: space-between;
    align-items: center;
    padding: 15px 20px;
    background: linear-gradient(to bottom, #6a7a8e, #4a5a6e);
    color: #ffffff;
    cursor: pointer;
    transition: background 0.3s ease;
    user-select: none;
    list-style: none; /* 隐藏默认的三角箭头 (标准方式) */
}
/* 针对 Webkit 浏览器 (Chrome, Safari) 隐藏默认箭头 */
.status-summary::-webkit-details-marker {
    display: none;
}
.status-summary:hover {
    background: linear-gradient(to bottom, #7b8aa0, #5a6a7e);
}
/* 角色信息（名字和等级）容器 */
.char-info {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
}
.char-name {
    font-weight: 600;
    font-size: 1.15em;
    line-height: 1.2;
}
.char-level {
    font-size: 0.85em;
    opacity: 0.85;
    margin-top: 2px;
}
/* 自定义切换图标 */
.toggle-icon {
    font-size: 1.4em;
    transition: transform 0.35s cubic-bezier(0.68, -0.55, 0.27, 1.55);
    /* 初始状态是关闭的 */
    transform: rotate(0deg);
}
/* 当 details 展开时，旋转图标 */
.status-details[open] > .status-summary .toggle-icon {
    transform: rotate(180deg);
}
/* 包裹折叠内容的容器，用于动画 */
.status-content-wrapper {
    background-color: #fafafa;
    border-top: 1px solid #e0e0e0;
    padding: 0 20px; /* 关闭时左右有padding，上下为0 */
    /* overflow: hidden;  */ /* 这个 overflow 移到 container 上更好 */
    /* 动画关键：使用 max-height 和 opacity */
    max-height: 0;
    opacity: 0;
    overflow: hidden; /* 隐藏内部溢出内容 */
    transition: max-height 0.4s ease-in-out, opacity 0.3s ease-in-out, padding 0.4s ease-in-out;
}
/* 当 details 展开时，显示内容 */
.status-details[open] > .status-content-wrapper {
    max-height: 85vh; /* 设置一个足够大的展开高度 */
    opacity: 1;
    padding: 20px; /* 展开时上下左右添加内边距 */
    overflow-y: auto; /* 如果内容过多，允许滚动 */
}
/* --- 以下是内部具体内容的样式 (基本不变) --- */
/* 内容区域分块样式 */
.status-section {
    margin-bottom: 18px;
    padding-bottom: 12px;
    border-bottom: 1px solid #e8e8e8;
}
.status-section:last-child {
    margin-bottom: 0;
    padding-bottom: 0;
    border-bottom: none;
}
.status-section h4 {
    font-size: 1.05em;
    font-weight: 600;
    color: #2c3e50;
    margin-bottom: 10px;
    border-left: 4px solid #5dade2;
    padding-left: 10px;
}
.status-section p,
.status-section ul {
    font-size: 0.95em;
    color: #444;
    line-height: 1.7;
}
.status-section ul {
    list-style: none;
    padding-left: 5px;
}
.status-section li {
    margin-bottom: 4px;
}
.status-section small {
    color: #777;
    font-size: 0.85em;
    margin-left: 6px;
    font-style: italic;
}
/* 魂力条样式 */
.soul-power-bar {
    width: 100%;
    height: 22px;
    background-color: #e9ecef;
    border-radius: 11px;
    position: relative;
    overflow: hidden;
    border: 1px solid #dce1e5;
    box-shadow: inset 0 1px 2px rgba(0,0,0,0.05);
}
.soul-power-fill {
    height: 100%;
    background: linear-gradient(90deg, #5ab9ea 0%, #3498db 100%);
    border-radius: 10px 0 0 10px;
    transition: width 0.5s ease-in-out;
    position: relative;
}
.soul-power-fill::after { /* 光泽效果 */
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 50%;
    background: linear-gradient(to bottom, rgba(255,255,255,0.3), rgba(255,255,255,0));
    border-radius: 10px 10px 0 0;
}
.soul-power-fill[style*="width: 100%"] {
    border-radius: 10px;
}
.soul-power-fill[style*="width: 100%"]::after {
    border-radius: 10px 10px 0 0;
}
.soul-power-text {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    font-size: 0.8em;
    font-weight: bold;
    color: #ffffff;
    text-shadow: 1px 1px 1px rgba(0, 0, 0, 0.4);
    white-space: nowrap;
}
.soul-power-text small {
    color: #e0e0e0;
    font-weight: normal;
    font-style: normal;
}
/* 响应式调整 */
@media (max-width: 480px) {
    .status-bar-container {
        width: 95%;
        margin: 15px auto;
    }
    .status-summary { /* 调整 summary 的 padding */
        padding: 12px 15px;
    }
    .status-content-wrapper { /* 调整 content wrapper 的 padding */
        padding: 0 15px;
    }
    .status-details[open] > .status-content-wrapper {
         padding: 15px;
    }
    .char-name { font-size: 1.1em; }
    .char-level { font-size: 0.8em; }
    .status-section h4 { font-size: 1em; }
    .status-section p, .status-section ul { font-size: 0.9em; }
}
/* 雌小鬼吐槽 */
.aa * {box-sizing: border-box;}
.bb {display: none;}
.aa {position: relative;text-align: center;left: 12%;}
.cc {opacity: 0;visibility: hidden;position: absolute;bottom: 100%;left: 40%;transform: translateX(-50%);margin-bottom: 25px;width: 280px;padding: 10px;background-color: #f1e4ff;border-radius: 15px;}
.cc::after {content: '';position: absolute;bottom: -20px;left: 50%;transform: translateX(-50%);border: 10px solid transparent;border-top-color: #ffffff;}
.dd {max-height: 150px;overflow-y: auto;padding-right: 10px;}
label:has(.bb:checked) ~ .cc {opacity: 1;visibility: visible;}
.aa label img {cursor: pointer;transition: transform 0.2s ease;}
@media (max-width: 768px) {.cc {width: 90%;max-width: 260px;}}
/* 幕后采访样式 */
.interview-wrap {
  background: linear-gradient(to right, #fa709a 0%, #fee140 100%);
  padding: 3px;
  border-radius: 15px;
  margin: 20px 0;
}
.interview-card {
  background: #fff;
  border-radius: 13px;
  padding: 20px;
}
.interview-header {
  display: flex;
  align-items: center;
  margin-bottom: 20px;
  padding-bottom: 15px;
  border-bottom: 2px solid #f0f0f0;
}
.interview-avatar {
  width: 50px;
  height: 50px;
  background: linear-gradient(135deg, #fa709a, #fee140);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  flex-shrink: 0;
}
.interview-info {
  margin-left: 15px;
}
.interview-name {
  font-weight: bold;
  font-size: 18px;
  color: #333;
}
.interview-status {
  font-size: 12px;
  color: #999;
  margin-top: 2px;
}
/* 问答区域 */
.interview-qa {
  margin-bottom: 15px;
  border-radius: 12px;
  overflow: hidden;
  border: 2px solid;
}
.interview-qa:last-child {
  margin-bottom: 0;
}
/* Q1 - 蓝色主题 */
.qa-1 {
  border-color: #64b5f6;
  background: #e3f2fd;
}
.qa-1 .qa-question {
  background: linear-gradient(135deg, #42a5f5, #1e88e5);
}
/* Q2 - 紫色主题 */
.qa-2 {
  border-color: #ba68c8;
  background: #f3e5f5;
}
.qa-2 .qa-question {
  background: linear-gradient(135deg, #ab47bc, #8e24aa);
}
/* Q3 - 橙色主题 */
.qa-3 {
  border-color: #ffb74d;
  background: #fff3e0;
}
.qa-3 .qa-question {
  background: linear-gradient(135deg, #ffa726, #fb8c00);
}
.qa-question {
  color: white;
  padding: 12px 15px;
  font-weight: bold;
  font-size: 14px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.qa-answer {
  padding: 15px;
  line-height: 1.8;
  font-size: 14px;
  color: #333;
}
/* 对话语言样式 */
.speech {
  color: #1976d2;
  font-weight: 500;
}
.qa-answer em {
  color: #6a1b9a;
  font-style: italic;
  background: rgba(156, 39, 176, 0.1);
  padding: 2px 4px;
  border-radius: 3px;
}
